using System.ComponentModel.DataAnnotations;
namespace Tamayoz.Models;
public class Service { public int Id { get; set; } [Required, StringLength(120)] public string Name { get; set; } = string.Empty; [Required, StringLength(280)] public string ShortDescription { get; set; } = string.Empty; [Required, StringLength(3000)] public string Description { get; set; } = string.Empty; [Range(0, 999999)] public decimal? Price { get; set; } [Required, StringLength(100)] public string EstimatedDuration { get; set; } = string.Empty; [Url, StringLength(500)] public string? ImageUrl { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? UpdatedAt { get; set; } public ICollection<ServiceRequest> Requests { get; set; } = new List<ServiceRequest>(); }
